import { test, expect } from '@playwright/test';
import { capboApiRequest, ensureCapboAccessToken, resolveApiFirstOptions } from '../helpers/capbo-api';

test.describe("Partners · API", () => {
  test.setTimeout(60_000);

  test("API · create Partners", async ({ request }) => {
    const token = await ensureCapboAccessToken(request);
    test.skip(!token, 'No CapBO token — run a UI Foreground test once to cache SSO');

    await test.step("POST /api/partners — create", async () => {
      const res = await capboApiRequest(request, {
        method: "POST",
        path: "/api/partners",
        body: {"code":"code-kyx95","name":"name-kyx95","display_label":"name-kyx95"},
        token,
      });
      const status = res.status();
      const raw = await res.text();
      expect([200,201].includes(status), `HTTP ${status}: ${raw.slice(0, 300)}`).toBeTruthy();
      expect(raw).toContain("name-kyx95");
    });

    await test.step("GET /api/partners (search) — verify", async () => {
      const res = await capboApiRequest(request, {
        method: "GET",
        path: "/api/partners?search=name-kyx95",
        token,
      });
      const status = res.status();
      const raw = await res.text();
      expect([200].includes(status), `HTTP ${status}: ${raw.slice(0, 300)}`).toBeTruthy();
      expect(raw).toContain("name-kyx95");
    });

  });
});
